TRIGGER_SQL = """
CREATE OR REPLACE FUNCTION spatial_layer_style_scope() RETURNS trigger AS $$
DECLARE
    laag record;
    stijl record;
    doel record;
BEGIN
    SELECT access_through_id, access_id INTO laag FROM spatial_layer WHERE id = NEW.layer_id;
    -- Een koppelrij van een projectlaag volgt de scope van de laag; die van een
    -- organisatielaag ook, behalve als het een projectrij is.
    IF laag.access_through_id = 'project'
       OR (laag.access_through_id = 'organisation' AND NEW.access_through_id IS DISTINCT FROM 'project') THEN
        NEW.access_through_id := laag.access_through_id;
        NEW.access_id := laag.access_id;
    END IF;
    IF NEW.access_through_id = 'organisation' AND NEW.access_id IS NULL THEN
        RAISE EXCEPTION 'spatial_layer_style: een stijlkoppeling van een organisatie heeft access_id nodig'
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.access_through_id = 'project' AND NEW.access_id IS NULL THEN
        RAISE EXCEPTION 'spatial_layer_style: een stijlkoppeling van een project heeft access_id nodig'
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.access_through_id NOT IN ('organisation', 'project') AND NEW.access_id IS NOT NULL THEN
        RAISE EXCEPTION 'spatial_layer_style: een applicatiebrede stijlkoppeling heeft geen access_id'
            USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.style_id IS NOT NULL THEN
        SELECT access_through_id, access_id INTO stijl FROM spatial_style WHERE id = NEW.style_id;
        -- Een organisatiestijl hoort bij een rij van die organisatie of bij een projectrij.
        IF stijl.access_through_id = 'organisation' AND NEW.access_through_id <> 'project'
           AND (NEW.access_through_id <> 'organisation' OR NEW.access_id IS DISTINCT FROM stijl.access_id) THEN
            RAISE EXCEPTION 'spatial_layer_style: de stijl is van een andere organisatie dan de stijlkoppeling'
                USING ERRCODE = 'check_violation';
        END IF;
        IF stijl.access_through_id = 'project'
           AND (NEW.access_through_id <> 'project' OR NEW.access_id IS DISTINCT FROM stijl.access_id) THEN
            RAISE EXCEPTION 'spatial_layer_style: de stijl is van een ander project dan de stijlkoppeling'
                USING ERRCODE = 'check_violation';
        END IF;
    END IF;

    IF NEW.vervangt_id IS NOT NULL THEN
        SELECT layer_id, access_through_id, vervangt_id INTO doel
          FROM spatial_layer_style WHERE id = NEW.vervangt_id;
        IF NEW.vervangt_id = NEW.id OR doel.layer_id IS DISTINCT FROM NEW.layer_id THEN
            RAISE EXCEPTION 'spatial_layer_style: de vervangen stijlkoppeling hoort bij een andere kaartlaag'
                USING ERRCODE = 'check_violation';
        END IF;
        IF doel.vervangt_id IS NOT NULL THEN
            RAISE EXCEPTION 'spatial_layer_style: een stijlkoppeling die zelf iets vervangt kan niet vervangen worden'
                USING ERRCODE = 'check_violation';
        END IF;
        IF doel.access_through_id <> 'authenticated'
           AND NOT (NEW.access_through_id = 'project' AND doel.access_through_id = 'organisation') THEN
            RAISE EXCEPTION 'spatial_layer_style: alleen een applicatiebrede stijlkoppeling kan vervangen worden, door een projectrij ook die van een organisatie'
                USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
"""


